#!/usr/bin/env python3
"""Generate fig_aggregation_comparison: ASR vs K_eff scatter for 4 aggregation methods at K=3 and K=5."""
import sys, json, itertools, warnings
import numpy as np
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
from pathlib import Path
from collections import Counter

warnings.filterwarnings("ignore")

PROJECT_ROOT = Path("/root/cert_manip_resist_eval")
sys.path.insert(0, str(PROJECT_ROOT))

from src.unified_data_loader import (
    ALL_MODELS, DATASETS, ATTACKS,
    load_all_scores, load_pairs, load_mi_data,
    _is_valid_score,
)

EPS = 1e-6

# ── Aggregation functions ──
def agg_majority(votes, _w):
    c = Counter(votes)
    mc = c.most_common()
    if mc[0][1] >= (len(votes) // 2 + 1):
        return mc[0][0]
    for k, _ in mc:
        if k != "tie":
            return k
    return "tie"

def agg_threshold(votes, _w):
    if all(v == votes[0] for v in votes):
        return votes[0]
    return "ABSTAIN"

def agg_weighted(votes, weights):
    scores = {}
    for v, w in zip(votes, weights):
        scores[v] = scores.get(v, 0.0) + w
    ranked = sorted(scores.items(), key=lambda x: -x[1])
    if len(ranked) >= 2 and abs(ranked[0][1] - ranked[1][1]) < 1e-12:
        return "TIE"
    return ranked[0][0]

def agg_bayesian(votes, reliabilities):
    log_pa, log_pb = 0.0, 0.0
    for v, p in zip(votes, reliabilities):
        p = max(min(p, 0.999), 0.001)
        lp, l1p = np.log(p), np.log(1.0 - p)
        if v == "A":
            log_pa += lp; log_pb += l1p
        elif v == "B":
            log_pa += l1p; log_pb += lp
    if log_pa > log_pb:
        return "A"
    if log_pb > log_pa:
        return "B"
    return "TIE"

METHODS = {
    "Majority": agg_majority,
    "Weighted": agg_weighted,
    "Threshold": agg_threshold,
    "Bayesian": agg_bayesian,
}

# ── Helpers ──
def mi_based_keff(mi_matrix, model_indices):
    K = len(model_indices)
    if K <= 1:
        return 1.0
    keff = 0.0
    for i_idx in model_indices:
        term = 1.0
        for j_idx in model_indices:
            if i_idx != j_idx:
                term += np.exp(-2 * mi_matrix[i_idx, j_idx])
        keff += term
    return keff / K

def compute_panel_asr(jids, clean_ds, attacked_ds_atk, pairs, agg_fn, weights):
    n = min(len(pairs), *(len(clean_ds[j]) for j in jids),
            *(len(attacked_ds_atk[j]) for j in jids))
    n_flips = n_correct = 0
    w = [weights[j] for j in jids]
    for i in range(n):
        if not all(_is_valid_score(clean_ds[j][i]) for j in jids):
            continue
        if not all(_is_valid_score(attacked_ds_atk[j][i]) for j in jids):
            continue
        gt = pairs[i]["ground_truth_winner"]
        cv = agg_fn([clean_ds[j][i]["winner"] for j in jids], w)
        if cv != gt:
            continue
        n_correct += 1
        av = agg_fn([attacked_ds_atk[j][i]["winner"] for j in jids], w)
        if av != gt:
            n_flips += 1
    return n_flips / max(n_correct, 1)

def compute_clean_accuracy(clean_list, pairs):
    n = min(len(clean_list), len(pairs))
    correct = total = 0
    for i in range(n):
        if not _is_valid_score(clean_list[i]):
            continue
        total += 1
        if clean_list[i]["winner"] == pairs[i]["ground_truth_winner"]:
            correct += 1
    return correct / max(total, 1)


# ── Main ──
print("Loading data...")
all_scores = load_all_scores()
all_pairs = load_pairs()
mi_data = load_mi_data()
N = len(ALL_MODELS)

# Average MI matrix across datasets
mi_avg = np.zeros((N, N))
n_ds = 0
for ds in DATASETS:
    if ds in mi_data:
