EPS = 1e-6

def agg_majority(votes, _w):
    c = Counter(votes)
    mc = c.most_common()
    if mc[0][1] >= (len(votes) // 2 + 1):
        return mc[0][0]
    for k, _ in mc:
        if k != "tie":
            return k
    return "tie"

def agg_threshold(votes, _w):
    if all(v == votes[0] for v in votes):
        return votes[0]
    return "ABSTAIN"

def agg_weighted(votes, weights):
    scores = {}
    for v, w in zip(votes, weights):
        scores[v] = scores.get(v, 0.0) + w
    ranked = sorted(scores.items(), key=lambda x: -x[1])
    if len(ranked) >= 2 and abs(ranked[0][1] - ranked[1][1]) < 1e-12:
        return "TIE"
    return ranked[0][0]

def agg_bayesian(votes, reliabilities):
    log_pa, log_pb = 0.0, 0.0
    for v, p in zip(votes, reliabilities):
        p = max(min(p, 0.999), 0.001)
        lp, l1p = np.log(p), np.log(1.0 - p)
        if v == "A":
            log_pa += lp; log_pb += l1p
        elif v == "B":
            log_pa += l1p; log_pb += lp
    if log_pa > log_pb:
        return "A"
    if log_pb > log_pa:
        return "B"
    return "TIE"

